// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        c.setOwner(actor); // actor becomes owner

        vm.prank(actor);
        c.setOwner(newOwner);

        // General rule: after the owner calls setOwner(newOwner), owner == newOwner.
        assertTrue(c.owner() == newOwner);
    }
}

